```cpp
class Solution {
public:
    int firstMissingPositive(vector<int>& nums) {
        int n = nums.size();

        // Step 1: Place numbers at their correct index
        for (int i = 0; i < n; i++) {
            // Keep swapping until nums[i] is either out of range
            // or already at the right position
            while (nums[i] >= 1 && nums[i] <= n && nums[nums[i] - 1] != nums[i]) {
                swap(nums[i], nums[nums[i] - 1]);
            }
        }

        // Step 2: Find the first place where index != value-1
        for (int i = 0; i < n; i++) {
            if (nums[i] != i + 1) {
                return i + 1;
            }
        }

        // Step 3: If all 1..n are present, answer is n+1
        return n + 1;
    }
};
```

