#include <stdio.h>

int firstMissingPositive(int* nums, int numsSize) {
    int i = 0;

    // Step 1: Place numbers at their correct index
    while (i < numsSize) {
        int correctIndex = nums[i] - 1;

        // Check: nums[i] should be between 1..n and not already in right place
        if (nums[i] > 0 && nums[i] <= numsSize && nums[i] != nums[correctIndex]) {
            // swap nums[i] with nums[correctIndex]
            int temp = nums[i];
            nums[i] = nums[correctIndex];
            nums[correctIndex] = temp;
        } else {
            i++;
        }
    }

    // Step 2: Find first missing positive
    for (i = 0; i < numsSize; i++) {
        if (nums[i] != i + 1) {
            return i + 1;
        }
    }

    // Step 3: If all 1..n are present
    return numsSize + 1;
}

// Test code
int main() {
    int nums[] = {3, 4, -1, 1};
    int size = sizeof(nums) / sizeof(nums[0]);

    int ans = firstMissingPositive(nums, size);
    printf("First missing positive: %d\n", ans);

    return 0;
}
```

---

### 🔹 Dry run on `[3,4,-1,1]`
- Start: `[3,4,-1,1]`  
- Swap `3` into index `2` → `[ -1,4,3,1 ]`  
- Swap `-1` ignored (not in range)  
- Swap `4` into index `3` → `[ -1,1,3,4 ]`  
- Swap `1` into index `0` → `[ 1,-1,3,4 ]`  

Final array: `[1,-1,3,4]`  
- index 0 → `1` ✅  
- index 1 → `-1` ❌ (expected `2`) → answer = **2**.  

